{
  "name": "mighty-instincts",
  "version": "0.11.2",
  "description": "OpenCode V2 plugin that observes session activity and distils it into ECC-compatible instincts, exposes the ECC instinct CLI as slash commands, and (OpenCode 2 TUI) shows a collapsible sidebar board summarising instincts, observations and skill evals.",
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": "./index.js",
    "./tui": "./tui.js",
    "./package.json": "./package.json"
  },
  "files": [
    "index.js",
    "tui.js",
    "sidebar.js",
    "lib/",
    "vendor/",
    "README.md",
    "docs/",
    "CHANGELOG.md",
    "LICENSE",
    "NOTICE"
  ],
  "scripts": {
    "test": "node smoke-test.mjs && bun smoke-test.mjs",
    "check": "bash scripts/check.sh",
    "hooks": "git config core.hooksPath .githooks && echo hooks installed",
    "release": "bash scripts/release.sh"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "instincts",
    "continuous-learning",
    "ecc"
  ],
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.18 <3"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Mightybeast12/mighty-instincts.git"
  },
  "bugs": {
    "url": "https://github.com/Mightybeast12/mighty-instincts/issues"
  },
  "homepage": "https://github.com/Mightybeast12/mighty-instincts#readme",
  "author": "Firat Honca",
  "license": "MIT"
}
